package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"time"
)

const (
	serviceSecret = "k8s-pipeline-shared-secret-2024"
	tokenTTL      = 300 // 5 minutes
)

// CrossServiceToken represents an authenticated redirect token
// used between CI/CD pipeline stages (builder -> deployer -> monitor)
type CrossServiceToken struct {
	TargetURL string
	Issuer    string
	Timestamp int64
	Signature string
}

func computeHMAC(message, secret string) string {
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(message))
	return hex.EncodeToString(mac.Sum(nil))
}

func validateSignature(token CrossServiceToken) bool {
	message := fmt.Sprintf("%s|%s|%d", token.Issuer, token.TargetURL, token.Timestamp)
	expected := computeHMAC(message, serviceSecret)
	return hmac.Equal([]byte(expected), []byte(token.Signature))
}

// normalizeServiceURL ensures the URL is in canonical form for our
// internal service mesh. Strips fragments, normalizes path.
func normalizeServiceURL(rawURL string) (string, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return "", fmt.Errorf("invalid URL: %w", err)
	}
	parsed.Fragment = ""
	parsed.RawQuery = parsed.Query().Encode()
	return parsed.String(), nil
}

// isInternalService validates that the target belongs to our service mesh.
// Internal services use the pattern: https://<service>.internal.pipeline.io
// or relative paths for same-origin redirects.
func isInternalService(targetURL string) bool {
	// Allow relative paths (same-origin)
	if !strings.Contains(targetURL, "://") {
		return true
	}

	parsed, err := url.Parse(targetURL)
	if err != nil {
		return false
	}

	// Verify the host matches our internal service mesh pattern
	host := strings.ToLower(parsed.Hostname())
	if strings.HasSuffix(host, ".internal.pipeline.io") {
		return true
	}

	// Allow the base domain itself
	if host == "internal.pipeline.io" {
		return true
	}

	return false
}

// handlePipelineRedirect processes authenticated cross-service redirects
// in the CI/CD pipeline. Services sign redirect targets to prevent tampering.
func handlePipelineRedirect(w http.ResponseWriter, r *http.Request) {
	target := r.URL.Query().Get("target")
	issuer := r.URL.Query().Get("issuer")
	sig := r.URL.Query().Get("sig")
	ts := r.URL.Query().Get("ts")

	if target == "" || issuer == "" || sig == "" || ts == "" {
		http.Error(w, "missing required parameters", http.StatusBadRequest)
		return
	}

	var timestamp int64
	fmt.Sscanf(ts, "%d", &timestamp)

	// Check token freshness
	now := time.Now().Unix()
	if now-timestamp > tokenTTL {
		http.Error(w, "token expired", http.StatusUnauthorized)
		return
	}

	// Normalize the URL before validation
	normalizedTarget, err := normalizeServiceURL(target)
	if err != nil {
		http.Error(w, "invalid target URL", http.StatusBadRequest)
		return
	}

	// Validate the cryptographic signature
	token := CrossServiceToken{
		TargetURL: target, // Signature computed over original target
		Issuer:    issuer,
		Timestamp: timestamp,
		Signature: sig,
	}

	if !validateSignature(token) {
		http.Error(w, "invalid signature", http.StatusForbidden)
		return
	}

	// Verify the normalized URL points to an internal service
	if !isInternalService(normalizedTarget) {
		http.Error(w, "target is not an internal service", http.StatusForbidden)
		return
	}

	// Redirect to the target service
	http.Redirect(w, r, normalizedTarget, http.StatusFound)
}

// handleHealthCheck provides liveness probe for k8s
func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/pipeline/redirect", handlePipelineRedirect)
	mux.HandleFunc("/health", handleHealthCheck)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Pipeline redirect service starting on :8443")
	if err := server.ListenAndServe(); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}
